// Spot the Flaw: the game on the Evaluators page. Data comes from the page's #spot-data block,
// generated by tools/build_spot_flaw.py from the public training set.
(function () {
  "use strict";
  var DATA = JSON.parse(document.getElementById("spot-data").textContent);
  var cases = DATA.cases, stats = DATA.stats;
  var $ = function (id) { return document.getElementById(id); };
  var hasModel = cases.length > 0 && Array.isArray(cases[0].model);
  var state = { i: 0, picked: null, you: 0, longer: 0, kw: 0, model: 0, done: 0 };

  function judgeText(pick, correct) {
    if (pick === "tie") return { t: "could not tell (tie)", c: "tie" };
    var side = pick === "chosen" ? correct : (correct === "a" ? "b" : "a");
    var ok = pick === "chosen";
    return { t: "picked " + side.toUpperCase() + (ok ? ", right" : ", fooled"), c: ok ? "ok" : "no" };
  }

  function setAnswer(btn, text) {
    btn.querySelector(".text").textContent = text;
    btn.classList.remove("is-right", "is-wrong");
    btn.removeAttribute("aria-disabled");
    var st = btn.querySelector(".stamp"); st.hidden = true; st.textContent = "";
  }

  function render() {
    var c = cases[state.i];
    state.picked = null;
    $("progress").textContent = "Case " + (state.i + 1) + " of " + cases.length;
    $("case-id").textContent = "#" + c.id;
    $("prompt").textContent = c.prompt;
    setAnswer($("ans-a"), c.a);
    setAnswer($("ans-b"), c.b);
    $("reveal").hidden = true;
    $("summary").hidden = true;
    $("hint").hidden = false;
    $("next").textContent = state.i + 1 < cases.length ? "Next case" : "See your result";
  }

  function choose(side) {
    if (state.picked) return;
    var c = cases[state.i];
    state.picked = side;
    var right = side === c.correct;
    state.done += 1;
    if (right) state.you += 1;
    if (c.longer === "chosen") state.longer += 1; else if (c.longer === "tie") state.longer += 0.5;
    if (c.keywords === "chosen") state.kw += 1; else if (c.keywords === "tie") state.kw += 0.5;
    if (hasModel) {
      var okRuns = c.model.filter(function (p) { return p === "chosen"; }).length;
      state.model += okRuns / c.model.length;
      var mt = $("j-model");
      var all = c.model.length === 1 ? "its run" : c.model.length === 2 ? "both runs" : "all " + c.model.length + " runs";
      if (okRuns === c.model.length) { mt.textContent = "right in " + all; mt.className = "res ok"; }
      else if (okRuns === 0) { mt.textContent = "fooled in " + all; mt.className = "res no"; }
      else { mt.textContent = "right in " + okRuns + " of " + c.model.length + " runs"; mt.className = "res tie"; }
    }
    ["a", "b"].forEach(function (s) {
      var btn = $("ans-" + s), st = btn.querySelector(".stamp");
      btn.setAttribute("aria-disabled", "true");
      btn.classList.add(s === c.correct ? "is-right" : "is-wrong");
      st.hidden = false;
      st.textContent = s === c.correct ? "SOUND" : "FLAWED";
    });
    $("verdict").textContent = right ? "Right. You trusted the sound review." : "Fooled. The review you picked has the flaw.";
    $("fam-code").textContent = c.family;
    $("fam-name").textContent = c.family_name;
    $("fam-desc").textContent = c.family_desc;
    $("flaw").textContent = c.flaw || "see the source advisory";
    var jl = judgeText(c.longer, c.correct), jk = judgeText(c.keywords, c.correct);
    $("j-longer").textContent = jl.t; $("j-longer").className = "res " + jl.c;
    $("j-kw").textContent = jk.t; $("j-kw").className = "res " + jk.c;
    $("source").href = c.source;
    $("source").textContent = c.source.replace(/^https:\/\//, "");
    $("hint").hidden = true;
    $("reveal").hidden = false;
    updateTally();
    $("next").focus({ preventScroll: true });
  }

  function fmt(x) { return (Math.round(x * 10) / 10).toString(); }
  function updateTally() {
    $("score-you").textContent = state.you;
    $("score-n").textContent = state.done;
    $("score-longer").textContent = fmt(state.longer);
    $("score-kw").textContent = fmt(state.kw);
    $("score-model").textContent = fmt(state.model);
  }

  function next() {
    if (state.i + 1 < cases.length) { state.i += 1; render(); $("game").scrollIntoView({ block: "start" }); return; }
    $("reveal").hidden = true;
    $("summary").hidden = false;
    $("sum-you").textContent = state.you + " / " + state.done;
    $("sum-text").textContent = "On the same cases the longer-answer judge scored " + fmt(state.longer) +
      (hasModel ? ", the keyword judge " + fmt(state.kw) + ", and our evaluator " + fmt(state.model) +
        ". The evaluator never trained on these cases; its score is the average of two training runs. " :
        " and the keyword judge " + fmt(state.kw) + ". ") +
      "A tie counts as half. A useful evaluator has to read what an answer claims, not how long or how alarming it sounds.";
    $("restart").focus({ preventScroll: true });
  }

  function restart() {
    state = { i: 0, picked: null, you: 0, longer: 0, kw: 0, model: 0, done: 0 };
    updateTally(); render();
    $("game").scrollIntoView({ block: "start" });
  }

  function chart() {
    var rows = [
      { name: "Longer answer wins", v: stats.longer, label: stats.longer + "%" },
      { name: "More security keywords wins", v: stats.keywords, label: stats.keywords + "%" },
      { name: "AdversarialEval, all training pairs", v: stats.full_lo, hi: stats.full_hi, label: Math.round(stats.full_lo) + " to " + Math.round(stats.full_hi) + "%", ours: true },
      { name: "AdversarialEval, demo cases held out", v: stats.held_lo, hi: stats.held_hi, label: Math.round(stats.held_lo) + " to " + Math.round(stats.held_hi) + "%", ours: true }
    ];
    var html = "";
    rows.forEach(function (r) {
      html += '<div class="numrow"><span class="k">' + r.name + '</span><span class="v' + (r.ours ? " ours" : "") + '">' + r.label + '</span>' +
        '<div class="track"><div class="fill' + (r.ours ? " ours" : "") + '" style="width:' + r.v + '%"></div><div class="coin"></div></div></div>';
    });
    $("chart").innerHTML = html;
    $("chart").setAttribute("aria-label", rows.map(function (r) { return r.name + " " + r.label; }).join("; "));
    $("n-val").textContent = stats.n;
  }

  function families() {
    var ul = $("families"), keys = Object.keys(DATA.families).sort(function (a, b) { return +a.slice(1) - +b.slice(1); });
    keys.forEach(function (k) {
      var li = document.createElement("li");
      var code = document.createElement("code"); code.textContent = "[" + k + "]";
      var st = document.createElement("strong"); st.textContent = DATA.families[k][0];
      var sp = document.createElement("span"); sp.textContent = DATA.families[k][1];
      li.append(code, st, sp); ul.appendChild(li);
    });
  }

  $("ans-a").addEventListener("click", function () { choose("a"); });
  $("ans-b").addEventListener("click", function () { choose("b"); });
  $("next").addEventListener("click", next);
  $("restart").addEventListener("click", restart);
  document.addEventListener("keydown", function (e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    var k = e.key.toLowerCase();
    if (!state.picked && (k === "a" || k === "b")) { choose(k); e.preventDefault(); }
    else if (state.picked && k === "n") { next(); e.preventDefault(); }
  });
  $("share").addEventListener("click", function () {
    var url = location.href.split("#")[0] + "#c-" + cases[state.i].id;
    var btn = $("share");
    function done(t) { btn.textContent = t; setTimeout(function () { btn.textContent = "Copy link to this case"; }, 2000); }
    try {
      navigator.clipboard.writeText(url).then(function () { done("Link copied"); }, function () { done(url); });
    } catch (e) { done(url); }
  });
  if (hasModel) {
    $("chip-model").hidden = false;
    $("judge-model").hidden = false;
    $("judge-model-k").hidden = false;
    if (DATA.model_note) { $("model-note").textContent = DATA.model_note; $("model-note").hidden = false; }
  }
  function fromHash() {
    var m = /^#c-([0-9a-f]{10})$/.exec(location.hash);
    if (!m) return false;
    for (var k = 0; k < cases.length; k++) { if (cases[k].id === m[1]) { state.i = k; return true; } }
    return false;
  }
  if (fromHash()) setTimeout(function () { $("game").scrollIntoView({ block: "start" }); }, 0);
  window.addEventListener("hashchange", function () { if (fromHash()) render(); });
  $("n-cases").textContent = cases.length;
  chart(); families(); updateTally(); render();
})();
